    ["Guide automatically resizes to the configured number of steps. Manual Resize is disabled while Auto Resize is enabled."] = "Der Guide passt seine Größe automatisch an die eingestellte Anzahl von Schritten an. Manuelle Größenänderung ist deaktiviert, solange Automatische Größe aktiviert ist.",
    ["If enabled, will show a progrerss bar for % based quests"] = "Wenn aktiviert, wird für prozentbasierte Quests ein Fortschrittsbalken angezeigt",
    ["If enabled, will show the progress of the guide as a count rather than %."] = "Wenn aktiviert, wird der Fortschritt des Guides als Anzahl statt in % angezeigt.",
    ["Left click to drag"] = "Linksklick zum Ziehen",
    ["Min Resize - Height"] = "Min. Größe - Höhe",
    ["Min Resize - Width"] = "Min. Größe - Breite",
    ["Minimum height (pixels) the guide window can be set to."] = "Minimale Höhe (Pixel), auf die das Guide-Fenster eingestellt werden kann.",
    ["Move, resize, and customize"] = "Verschieben, Größe ändern und anpassen",
    ["NOTE: Quest automation does not work in instances or in combat"] = "HINWEIS: Die Quest-Automatisierung funktioniert nicht in Instanzen oder im Kampf",
    ["Navigation and action buttons"] = "Navigations- und Aktionsschaltflächen",
    ["Next"] = "Weiter",
    ["No guide is currently loaded."] = "Es ist derzeit kein Guide geladen.",
    ["No guide loaded."] = "Kein Guide geladen.",
    ["Notes"] = "Notizen",
    ["Opens the WoWPro debug log so you can review recent messages."] = "Öffnet das WoWPro-Debug-Protokoll, damit du aktuelle Meldungen prüfen kannst.",
    ["Override Minimum Width"] = "Minimale Breite überschreiben",
    ["Overview"] = "Übersicht",
    ["Press Escape to close it and continue. Next bypasses this action."] = "Drücke Escape, um es zu schließen und fortzufahren. Weiter überspringt diese Aktion.",
    ["Quest Engine"] = "Quest-Engine",
    ["Quest-item, target, extra-action, and waypoint buttons appear beside steps when needed. Use them to act on the current task. TomTom or Carbonite provides navigation. If no action button is visible, it may not be needed for this step or may be disabled in settings."] = "Quest-Gegenstand-, Ziel-, Extra-Aktions- und Wegpunkt-Schaltflächen erscheinen bei Bedarf neben den Schritten. Verwende sie, um die aktuelle Aufgabe auszuführen. TomTom oder Carbonite stellt die Navigation bereit. Wenn keine Aktionsschaltfläche sichtbar ist, wird sie für diesen Schritt möglicherweise nicht benötigt oder ist in den Einstellungen deaktiviert.",
    ["Rank (Difficulty/Completeness)"] = "Rang (Schwierigkeit/Vollständigkeit)",
    ["Read the current guide"] = "Aktuellen Guide lesen",
    ["Recorder"] = "Aufzeichnung",
    ["Reopen the guide steps"] = "Guide-Schritte wieder öffnen",
    ["Replay Tutorial"] = "Tutorial erneut abspielen",
    ["Reset guide progress"] = "Guide-Fortschritt zurücksetzen",
    ["Reset or Delete"] = "Zurücksetzen oder löschen",
    ["Reset window"] = "Fenster zurücksetzen",
    ["Resetting WoW-Pro wipes saved state across all characters. Use the log tools first when troubleshooting."] = "Das Zurücksetzen von WoW-Pro löscht den gespeicherten Zustand aller Charaktere. Verwende bei der Fehlersuche zuerst die Protokollwerkzeuge.",
    ["Restart"] = "Neu starten",
    ["Restores the guide window's position, size, and scale without changing guide progress or other settings."] = "Stellt Position, Größe und Skalierung des Guide-Fensters wieder her, ohne Guide-Fortschritt oder andere Einstellungen zu ändern.",
    ["Resume"] = "Fortsetzen",
    ["Resume / Restart Tutorial"] = "Tutorial fortsetzen / neu starten",
    ["Resume tutorial?"] = "Tutorial fortsetzen?",
    ["Review the transcript to see the guide's instructions. When you are ready, click the document button again to close this window and continue the tour."] = "Lies die Abschrift, um die Anweisungen des Guides zu sehen. Wenn du bereit bist, klicke erneut auf die Dokument-Schaltfläche, um dieses Fenster zu schließen und die Tour fortzusetzen.",
    ["Select or Create"] = "Auswählen oder erstellen",
    ["Sets how many steps to show and auto-resizes the window to fit them. Only applies when Auto Resize is enabled. Sticky steps are not counted."] = "Legt fest, wie viele Schritte angezeigt werden, und passt die Fenstergröße automatisch an. Gilt nur, wenn Automatische Größe aktiviert ist. Angeheftete Schritte werden nicht gezählt.",
    ["Settings for the WoW-Pro addon's Achievements module."] = "Einstellungen für das Erfolge-Modul des WoW-Pro-Addons.",
    ["Settings for the WoW-Pro addon's Dailies module."] = "Einstellungen für das Tagesquest-Modul des WoW-Pro-Addons.",
    ["Settings for the WoW-Pro addon's Profession module."] = "Einstellungen für das Berufe-Modul des WoW-Pro-Addons.",
    ["Settings for the WoW-Pro addon's WorldEvents module."] = "Einstellungen für das Weltereignisse-Modul des WoW-Pro-Addons.",
    ["Settings for the WoW-Pro addon's leveling module."] = "Einstellungen für das Level-Modul des WoW-Pro-Addons.",
    ["Sharing"] = "Teilen",
    ["Show Extra Action Button"] = "Extra-Aktions-Schaltfläche anzeigen",
    ["Show Item/Use Button"] = "Gegenstands-/Benutzen-Schaltfläche anzeigen",
    ["Show Jump Button"] = "Sprung-Schaltfläche anzeigen",
    ["Show Loot Icons"] = "Beute-Symbole anzeigen",
    ["Show Target Button"] = "Ziel-Schaltfläche anzeigen",
    ["Shows a resize handle at the corner opposite your anchor point.\n\nWhen enabled:\n- Drag the handle to manually resize the window\n- Window respects screen boundaries\n- Auto-resize is disabled\n\nWhen disabled:\n- Hides the handle and locks the current window size"] = "Zeigt einen Griff zum Größenändern in der Ecke gegenüber deinem Ankerpunkt an.\n\nWenn aktiviert:\n- Ziehe den Griff, um die Fenstergröße manuell zu ändern\n- Das Fenster beachtet Bildschirmgrenzen\n- Automatische Größenänderung ist deaktiviert\n\nWenn deaktiviert:\n- Blendet den Griff aus und sperrt die aktuelle Fenstergröße",
    ["Skip"] = "Überspringen",
    ["Spacing determines how much blank space is left between rows in the guide window. "] = "Der Abstand bestimmt, wie viel Leerraum zwischen den Zeilen im Guide-Fenster bleibt. ",
    ["Step Action Description"] = "Beschreibung der Schrittaktion",
    ["Steps"] = "Schritte",
    ["Steps, notes, and tracking"] = "Schritte, Notizen und Verfolgung",
    ["The check-mark toolbar button skips the current step on left-click and completes it on right-click. Row checkboxes also support manual control. Only use these when you need to override automatic tracking; there is no need to click them during the tour."] = "Die Häkchen-Schaltfläche in der Symbolleiste überspringt den aktuellen Schritt per Linksklick und schließt ihn per Rechtsklick ab. Auch die Kontrollkästchen der Zeilen erlauben manuelle Steuerung. Verwende diese nur, wenn du die automatische Verfolgung überschreiben musst; während der Tour müssen sie nicht angeklickt werden.",
    ["The circular-arrow button resets the current guide's progress. Use it only when you intend to start that guide over. The tutorial never activates this button."] = "Die Kreispfeil-Schaltfläche setzt den Fortschritt des aktuellen Guides zurück. Verwende sie nur, wenn du diesen Guide neu beginnen möchtest. Das Tutorial aktiviert diese Schaltfläche nie.",
    ["The document button opens the full transcript of your current guide. Use it to review earlier instructions or see what comes next without skipping active steps."] = "Die Dokument-Schaltfläche öffnet die vollständige Abschrift deines aktuellen Guides. So kannst du frühere Anweisungen nachlesen oder sehen, was als Nächstes kommt, ohne aktive Schritte zu überspringen.",
    ["The guide shows your next task, with extra instructions and objective tracking below it. Steps advance automatically as quests and objectives update. Guide Display settings control notes, tracking, and how many steps you see."] = "Der Guide zeigt deine nächste Aufgabe, darunter zusätzliche Anweisungen und die Zielverfolgung. Die Schritte werden automatisch fortgeschritten, wenn Quests und Ziele aktualisiert werden. Die Einstellungen der Guide-Anzeige steuern Notizen, Verfolgung und die Anzahl der sichtbaren Schritte.",
    ["The module for your current guide is not loaded."] = "Das Modul für deinen aktuellen Guide ist nicht geladen.",
    ["The saved tutorial topic is invalid. Restarting the tour from the beginning."] = "Das gespeicherte Tutorial-Thema ist ungültig. Die Tour wird von Anfang an neu gestartet.",
    ["The title bar names your current guide and shows its progress. Double-click it to collapse or expand the guide steps."] = "Die Titelleiste nennt deinen aktuellen Guide und zeigt seinen Fortschritt. Doppelklicke sie, um die Guide-Schritte ein- oder auszuklappen.",
    ["The title bar stays visible while the guide steps are collapsed. Double-click the highlighted title bar again to reopen the steps and continue the tour."] = "Die Titelleiste bleibt sichtbar, während die Guide-Schritte ausgeblendet sind. Doppelklicke die hervorgehobene Titelleiste erneut, um die Schritte wieder zu öffnen und die Tour fortzusetzen.",
    ["The tutorial cannot start during combat. Try again after combat ends."] = "Das Tutorial kann während eines Kampfes nicht gestartet werden. Versuche es nach dem Kampf erneut.",
    ["This feature is currently hidden or unavailable. You can continue the tour without enabling it."] = "Diese Funktion ist derzeit ausgeblendet oder nicht verfügbar. Du kannst die Tour fortsetzen, ohne sie zu aktivieren.",
    ["Title Bar & Button Bar"] = "Titelleiste & Schaltflächenleiste",
    ["Title and progress"] = "Titel und Fortschritt",
    ["Tools"] = "Werkzeuge",
    ["Treat quests completed by another character in your Warband as completed for step filtering."] = "Behandelt Quests, die ein anderer Charakter deiner Kriegsmeute abgeschlossen hat, bei der Schrittfilterung als abgeschlossen.",
    ["Troubleshooting"] = "Fehlersuche",
    ["Try it: double-click the title bar to collapse the guide steps. The tour will then ask you to reopen them before continuing. Next bypasses this action."] = "Probier es: Doppelklicke auf die Titelleiste, um die Guide-Schritte auszublenden. Die Tour bittet dich dann, sie wieder zu öffnen, bevor sie fortfährt. Weiter überspringt diese Aktion.",
    ["Try it: open WoW-Pro options from the gear menu. The tour will then ask you to close options before continuing. Next bypasses this action."] = "Probier es: Öffne die WoW-Pro-Optionen über das Zahnradmenü. Die Tour bittet dich dann, die Optionen zu schließen, bevor sie fortfährt. Weiter überspringt diese Aktion.",
    ["Try it: open the Guide List with the horn button. The tour will then ask you to close it before continuing. Next bypasses this action."] = "Probier es: Öffne die Guide-Liste über die Horn-Schaltfläche. Die Tour bittet dich dann, sie zu schließen, bevor sie fortfährt. Weiter überspringt diese Aktion.",
    ["Try it: open the current guide with the document button. The tour will then ask you to close it before continuing. Next bypasses this action."] = "Probier es: Öffne den aktuellen Guide über die Dokument-Schaltfläche. Die Tour bittet dich dann, ihn zu schließen, bevor sie fortfährt. Weiter überspringt diese Aktion.",
    ["Unknown distance"] = "Unbekannte Entfernung",
    ["Use Warband Quest Completion"] = "Quest-Abschluss der Kriegsmeute verwenden",
    ["Use the scroll bar (or scroll wheel) to see all the guides.\nClick to select a guide and load it.\nSHIFT+click a guide to reset it and then load it."] = "Verwende die Bildlaufleiste (oder das Mausrad), um alle Guides zu sehen.\nKlicke, um einen Guide auszuwählen und zu laden.\nUMSCHALT+Klick auf einen Guide setzt ihn zurück und lädt ihn dann.",
    ["Visibility"] = "Sichtbarkeit",
    ["Waypoint %d of %d"] = "Wegpunkt %d von %d",
    ["Welcome to WoW-Pro"] = "Willkommen bei WoW-Pro",
    ["When enabled: Drag the button bar, title bar, or settings button to move the window.\nWhen disabled: Window is locked in place."] = "Wenn aktiviert: Ziehe die Schaltflächenleiste, Titelleiste oder Einstellungs-Schaltfläche, um das Fenster zu verschieben.\nWenn deaktiviert: Das Fenster ist fixiert.",
    ["When enabled:\n- Target and Use buttons move to the left side of the window\n\nAuto-protect:\n- Automatically enables or disables to keep the buttons on-screen\n\nWhen disabled:\n- Buttons move to the right side of the window"] = "Wenn aktiviert:\n- Ziel- und Benutzen-Schaltflächen wandern auf die linke Fensterseite\n\nAutomatischer Schutz:\n- Aktiviert oder deaktiviert sie automatisch, damit die Schaltflächen auf dem Bildschirm bleiben\n\nWenn deaktiviert:\n- Die Schaltflächen wandern auf die rechte Fensterseite",
    ["Window Expansion Anchor"] = "Fenster-Erweiterungsanker",
    ["Window Recovery"] = "Fensterwiederherstellung",
