    ["Zone:"] = "Zone:",
    -- Recorder step-editor descriptions, part 1.
    ["Check if this is a chat step."] = "Markieren, wenn dies ein Chat-Schritt ist.",
    ["Check if this is a quest completion step NOT involving combat."] = "Markieren, wenn dies ein Questabschluss-Schritt ohne Kampf ist.",
    ["Check if this is an optional step."] = "Markieren, wenn dies ein optionaler Schritt ist.",
    ["Check if this is an sticky step."] = "Markieren, wenn dies ein angehefteter Schritt ist.",
    ["Check if this is an unsticky step."] = "Markieren, wenn dies ein nicht angehefteter Schritt ist.",
    ["Choose the quest you'd like to base this step on:"] = "Wähle die Quest, auf der dieser Schritt basieren soll:",
    ["Are you sure you want to delete this step?\n"] = "Bist du sicher, dass du diesen Schritt löschen möchtest?\n",
    ["Are you sure you want to delete this guide? This action cannot be undone.\n\n"] = "Bist du sicher, dass du diesen Guide löschen möchtest? Dies kann nicht rückgängig gemacht werden.\n\n",
    ["The step's type."] = "Der Typ des Schritts.",
    ["The main text for this step - often the quest name."] = "Der Haupttext für diesen Schritt – oft der Questname.",
    ["The main text for this step - often the quest title."] = "Der Haupttext für diesen Schritt – oft der Questtitel.",
    -- Recorder step-editor descriptions, part 2.
    ["Insert your current location and zone"] = "Aktuellen Standort und Zone einfügen",
    ["Jump to a step index while staying in the editor."] = "Zu einem Schrittindex springen, ohne den Editor zu verlassen.",
    ["Open a numbered list of every step in the current guide."] = "Öffnet eine nummerierte Liste aller Schritte im aktuellen Guide.",
    ["Registers the guide to be used. Current guide will be lost unless saved."] = "Registriert den Guide zur Verwendung. Der aktuelle Guide geht verloren, wenn er nicht gespeichert wurde.",
    ["The guide's type determines what kind of events will be listened for."] = "Der Guide-Typ bestimmt, auf welche Ereignisse gehört wird.",
    ["The quest you choose will determine what values are loaded into the step editor."] = "Die gewählte Quest bestimmt, welche Werte in den Schritt-Editor geladen werden.",
    ["The rank of the step. If you are unsure, leave it as 1."] = "Der Rang des Schritts. Wenn du unsicher bist, lasse ihn auf 1.",
    ["This step will be marked complete when you reach this level."] = "Dieser Schritt wird als abgeschlossen markiert, wenn du diese Stufe erreichst.",
    ["The quest tied to this step. If this quest is complete, this step will be checked off."] = "Die mit diesem Schritt verbundene Quest. Ist sie abgeschlossen, wird der Schritt abgehakt.",
    ["You need a zone tag if the coordinates lead to a point outside the guide's title zone."] = "Du brauchst einen Zonen-Tag, wenn die Koordinaten zu einem Punkt außerhalb der Titelzone des Guides führen.",
    ["Makes a run step complete based on coordinates rather than zone name."] = "Lässt einen Laufschritt anhand von Koordinaten statt des Zonennamens abschließen.",
    ["Makes a run step complete based on coordinates rather than zone name. (CC)"] = "Lässt einen Laufschritt anhand von Koordinaten statt des Zonennamens abschließen. (CC)",
    ["Makes a run step complete based on a series of coordinates, followed in order."] = "Lässt einen Laufschritt anhand einer Reihe von Koordinaten in Reihenfolge abschließen.",
    ["Makes a run step complete based on a series of coordinates, followed in order. (CS)"] = "Lässt einen Laufschritt anhand einer Reihe von Koordinaten in Reihenfolge abschließen. (CS)",
    ["Do not complete based on coordinates. Just show the dots. (CN)"] = "Nicht anhand von Koordinaten abschließen. Nur die Punkte anzeigen. (CN)",
    -- Recorder step-editor descriptions, part 3.
    ["All guides are listed here, including those that come with the addon and those you have created using the recorder."] = "Hier werden alle Guides aufgelistet, sowohl die mitgelieferten als auch die, die du mit dem Recorder erstellt hast.",
    ["Details on how to complete this step of the guide. No more than one or two sentences, please."] = "Details zur Erledigung dieses Schritts. Bitte nicht mehr als ein oder zwei Sätze.",
    ["Details on how to complete this step of the guide. No more than one or two sentences, please. Only leave blank for blatantly obvious steps."] = "Details zur Erledigung dieses Schritts. Bitte nicht mehr als ein oder zwei Sätze. Nur bei völlig offensichtlichen Schritten leer lassen.",
    ["Displayed if the user has the profession at the required skill level. Please enter in the form of 'Profession SkillLevel'."] = "Wird angezeigt, wenn der Nutzer den Beruf mit der nötigen Fertigkeit hat. Bitte im Format 'Beruf Fertigkeitsstufe' eingeben.",
    ["Enter coordinates for the step here, in the form '##.##,##.##'. Seperate multiple coordinates with semicolons (;)"] = "Gib hier die Koordinaten für den Schritt ein, im Format '##.##,##.##'. Mehrere Koordinaten mit Semikolon (;) trennen.",
    ["Full emitted guide lines for the current guide. The selected step is prefixed with >>."] = "Vollständige ausgegebene Guide-Zeilen für den aktuellen Guide. Der ausgewählte Schritt ist mit >> gekennzeichnet.",
    ["If a particular quest must be active, list it's QID here. Seperate multiple actives with AND/OR (&^)"] = "Wenn ein bestimmtes Quest aktiv sein muss, gib hier seine QID an. Mehrere aktive Quests mit AND/OR (&^) trennen.",
    ["If it would be helpful to provide an easy way to target a named mob, enter the mob's name here. Use only for hard to find mobs."] = "Wenn es hilfreich wäre, eine einfache Möglichkeit zum Anvisieren eines benannten Gegners zu bieten, gib hier seinen Namen ein. Nur für schwer zu findende Gegner verwenden.",
    ["If the quest has a prerequisite, list it's QID here. Seperate multiple prerequisites with AND/OR (&^)"] = "Wenn die Quest eine Voraussetzung hat, gib hier ihre QID an. Mehrere Voraussetzungen mit AND/OR (&^) trennen.",
    ["If the step compeltes when you loot a certain number of items, put the number here."] = "Wenn der Schritt abgeschlossen wird, sobald du eine bestimmte Anzahl Gegenstände erbeutest, gib die Anzahl hier ein.",
    ["If the step completes based on a scenario stage or objective, put the stage (or stage and objective separated by a ;) here."] = "Wenn der Schritt anhand einer Szenario-Stufe oder eines Ziels abgeschlossen wird, gib hier die Stufe (oder Stufe und Ziel durch ; getrennt) ein.",
    ["If the step completes based on one or two quest objectives, not the whole quest, you can enter the quest objective here. Seperate multiple objectives with semicolons (;)"] = "Wenn der Schritt anhand von ein oder zwei Questzielen statt der ganzen Quest abgeschlossen wird, kannst du das Questziel hier eingeben. Mehrere Ziele mit Semikolon (;) trennen.",
    ["If the step completes when you loot an item, put it's ID here."] = "Wenn der Schritt abgeschlossen wird, sobald du einen Gegenstand erbeutest, gib hier seine ID ein.",
    ["If the step requires you to use an item, put it's ID here."] = "Wenn der Schritt erfordert, dass du einen Gegenstand benutzt, gib hier seine ID ein.",
